import{_ as a,c as s,o as e,b0 as d}from"./chunks/framework.C5ev1SXp.js";const i="/scm-docs/assets/debug-tools.Cj69878w.svg",u=JSON.parse('{"title":"LV045-网络调试工具与抓包","description":null,"frontmatter":{"title":"LV045-网络调试工具与抓包","date":"2026-10-14T22:15:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d628e1bb0347a8c2e0d9b","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T22:15:00.230Z","fulluuid":"347a8c2e0d9b4a5f9e60c1d82b3f4a57","useduuid":"347a8c2e0"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d628e1bb0347a8c2e0d9b.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV045-网络调试工具与抓包.md","lastUpdated":1792231946000}'),n={name:"sdoc/advanced-chapter/network-basics/126d628e1bb0347a8c2e0d9b.md"};function r(h,t,p,l,o,c){return e(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="lv045-网络调试工具与抓包" tabindex="-1">LV045-网络调试工具与抓包 <a class="header-anchor" href="#lv045-网络调试工具与抓包" aria-label="Permalink to &quot;LV045-网络调试工具与抓包&quot;">​</a></h1><h2 id="一、-为什么要会看线上的包" tabindex="-1">一、 为什么要会看线上的包 <a class="header-anchor" href="#一、-为什么要会看线上的包" aria-label="Permalink to &quot;一、 为什么要会看线上的包&quot;">​</a></h2><h3 id="_1-日志只告诉你-自己这一侧看到了什么" tabindex="-1">1. 日志只告诉你&quot;自己这一侧看到了什么&quot; <a class="header-anchor" href="#_1-日志只告诉你-自己这一侧看到了什么" aria-label="Permalink to &quot;1. 日志只告诉你&quot;自己这一侧看到了什么&quot;&quot;">​</a></h3><p>排查网络问题时，最容易陷入的误区是&quot;只看自己这边的日志&quot;。日志的局限在于它只覆盖<strong>一个观测点</strong>：</p><ul><li>板子日志说&quot;没收到包&quot;——可能是包根本没发出来，也可能是发出来了但没到达板子；</li><li>PC 说&quot;超时&quot;——可能是请求没到达，也可能是到达了但应答没回来。</li></ul><p><strong>这两个观测点之间的事，日志永远看不到。</strong></p><h3 id="_2-抓包能看到线上真实发生了什么" tabindex="-1">2. 抓包能看到线上真实发生了什么 <a class="header-anchor" href="#_2-抓包能看到线上真实发生了什么" aria-label="Permalink to &quot;2. 抓包能看到线上真实发生了什么&quot;">​</a></h3><p>抓包（在链路上原样复制一份流量）补的就是这个缺口。它回答的是&quot;线上到底跑过什么包&quot;：</p><table tabindex="0"><thead><tr><th>问题</th><th>日志能答吗</th><th>抓包能答吗</th></tr></thead><tbody><tr><td>PC 到底把 ARP 请求发出去了吗</td><td>不能</td><td>能</td></tr><tr><td>板子的应答被交换机转发出来了吗</td><td>不能</td><td>能</td></tr><tr><td>请求与应答的间隔有多长</td><td>板子看不到发端时间</td><td>能</td></tr><tr><td>包里哪个字段不对</td><td>只能猜</td><td>逐字节看</td></tr></tbody></table><p>嵌入式开发的特殊性在于：<strong>板子本身没法装抓包工具</strong>，所以抓包点要选在 PC 侧（直连时 PC 网卡就能看到全部流量）或交换机的镜像口上。直连实验的抓包条件其实非常好——所有流量必过 PC 这块网卡。</p><img src="'+i+`" alt="排查层级与工具的对应关系"><h2 id="二、-三件套-ping、arp、ipconfig" tabindex="-1">二、 三件套：ping、arp、ipconfig <a class="header-anchor" href="#二、-三件套-ping、arp、ipconfig" aria-label="Permalink to &quot;二、 三件套：ping、arp、ipconfig&quot;">​</a></h2><h3 id="_1-ping-读输出里的三个数" tabindex="-1">1. ping：读输出里的三个数 <a class="header-anchor" href="#_1-ping-读输出里的三个数" aria-label="Permalink to &quot;1. ping：读输出里的三个数&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.30</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>输出里值得看的三样东西：</p><table tabindex="0"><thead><tr><th>输出</th><th>含义</th><th>排错用法</th></tr></thead><tbody><tr><td><code>时间=1ms</code> 这类值</td><td>往返时延</td><td>第一包明显慢是 ARP 的一问一答，正常现象</td></tr><tr><td><code>TTL=128</code></td><td>包的剩余跳数</td><td>板子直连时应该看到初始值；变小说明中间有路由器</td></tr><tr><td>丢包率</td><td>发了多少、回了多少</td><td>时通时不通时，先看丢包是不是集中在某几包</td></tr></tbody></table><p>第一包慢的原理见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.html">LV050-一次ping的完整旅程</a> 第二节。</p><h3 id="_2-arp-a-ip-neigh-看解析结果" tabindex="-1">2. arp -a / ip neigh：看解析结果 <a class="header-anchor" href="#_2-arp-a-ip-neigh-看解析结果" aria-label="Permalink to &quot;2. arp -a / ip neigh：看解析结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>命令</th><th>看什么</th></tr></thead><tbody><tr><td>Windows</td><td><code>arp -a</code></td><td>板子的 IP 有没有对应 MAC、MAC 对不对</td></tr><tr><td>Linux</td><td><code>ip neigh</code></td><td>同上，状态为 <code>REACHABLE</code> 才算学到</td></tr></tbody></table><p>两个典型结论：</p><p>（1）<strong>表里根本没有板子的 IP</strong>：ARP 没通，问题在链路层以下（网线、交换机、中断标志），轮不到 IP。</p><p>（2）<strong>IP 在但 MAC 不对</strong>：学到了错误的映射（IP 冲突或换了板子没清缓存），用 <code>arp -d 192.168.16.30</code> 删掉再 ping。</p><h3 id="_3-ipconfig-ip-addr-先确认你用的是哪块网卡" tabindex="-1">3. ipconfig / ip addr：先确认你用的是哪块网卡 <a class="header-anchor" href="#_3-ipconfig-ip-addr-先确认你用的是哪块网卡" aria-label="Permalink to &quot;3. ipconfig / ip addr：先确认你用的是哪块网卡&quot;">​</a></h3><p>笔记本上通常同时存在多块网卡：有线、WiFi、虚拟机虚拟网卡。直连实验最常见的低级错误是<strong>PC 把地址配到了 WiFi 网卡上</strong>，而有线网卡还是自动获取状态。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipconfig</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>要核对的是&quot;和板子连着的那块网卡&quot;的地址与掩码，而不是&quot;系统里存在这么一条配置&quot;。</p><h2 id="三、-快速连通性验证-nc" tabindex="-1">三、 快速连通性验证：nc <a class="header-anchor" href="#三、-快速连通性验证-nc" aria-label="Permalink to &quot;三、 快速连通性验证：nc&quot;">​</a></h2><h3 id="_1-测-tcp-确认端口能不能握手" tabindex="-1">1. 测 TCP：确认端口能不能握手 <a class="header-anchor" href="#_1-测-tcp-确认端口能不能握手" aria-label="Permalink to &quot;1. 测 TCP：确认端口能不能握手&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8888</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这条命令的价值在于<strong>把 TCP 与应用层协议解耦</strong>：不需要上位机脚本、不需要固件帧，只要握手成功，就说明 DM9000、lwIP、TCP、端口监听这条链全通。</p><p>三种结果对应三种结论：</p><table tabindex="0"><thead><tr><th>结果</th><th>结论</th></tr></thead><tbody><tr><td>立刻 <code>Connected to ...</code></td><td>传输层全通，问题在帧协议或上位机</td></tr><tr><td>一直挂起直到超时</td><td>端口没监听或 SYN 没到达，查 <code>IAP_TCP_EN</code>、端口占用</td></tr><tr><td>立刻 <code>Connection refused</code></td><td>到达了对端但端口没开（对 TCP 来说这是个&quot;好消息&quot;：IP 通了）</td></tr></tbody></table><p>本工程是单连接服务器，<strong>一个已建立的 nc 会话会占住通道</strong>：之后再用升级脚本连接会被 <code>tcp_abort</code> 拒绝。测完记得把 nc 关掉（见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a> 第三节）。</p><h3 id="_2-测-udp-确认服务器端口开着" tabindex="-1">2. 测 UDP：确认服务器端口开着 <a class="header-anchor" href="#_2-测-udp-确认服务器端口开着" aria-label="Permalink to &quot;2. 测 UDP：确认服务器端口开着&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 69</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>UDP 没有握手，所以 <code>nc -u</code> 的&quot;连通&quot;不代表什么；它的用法是<strong>发一个包出去，看服务器有没有反应</strong>。对 TFTP 来说更直接的办法是用 TFTP 客户端实际拉一次文件。</p><h2 id="四、-tcpdump-与-wireshark" tabindex="-1">四、 tcpdump 与 Wireshark <a class="header-anchor" href="#四、-tcpdump-与-wireshark" aria-label="Permalink to &quot;四、 tcpdump 与 Wireshark&quot;">​</a></h2><h3 id="_1-tcpdump-常用命令" tabindex="-1">1. tcpdump 常用命令 <a class="header-anchor" href="#_1-tcpdump-常用命令" aria-label="Permalink to &quot;1. tcpdump 常用命令&quot;">​</a></h3><p>Linux 下抓包的入口是 <code>tcpdump</code>（需要 root 或相应权限）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 抓指定网卡上与板子相关的全部流量</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.30</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只看 ARP 与 ICMP（ping 排错最常用的组合）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> or</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> icmp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 把抓到的包存成文件，之后用 Wireshark 打开慢慢看</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> board.pcap</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><code>-w</code> 写文件这个组合最值得记住：嵌入式现场往往只有串口和一根网线，先把流量录下来，事后在图形界面里分析。</p><h3 id="_2-wireshark-过滤表达式" tabindex="-1">2. Wireshark 过滤表达式 <a class="header-anchor" href="#_2-wireshark-过滤表达式" aria-label="Permalink to &quot;2. Wireshark 过滤表达式&quot;">​</a></h3><p>Windows 或图形环境里用 Wireshark，常用过滤写法：</p><table tabindex="0"><thead><tr><th>过滤表达式</th><th>看什么</th></tr></thead><tbody><tr><td><code>arp</code></td><td>ARP 的一问一答：请求广播、应答单播</td></tr><tr><td><code>icmp</code></td><td>ping 的请求与应答是否成对</td></tr><tr><td><code>tcp.port == 8888</code></td><td>升级通道的三次握手、数据段、重传</td></tr><tr><td><code>udp.port == 69 or udp</code></td><td>TFTP 的 RRQ、DATA、ACK</td></tr><tr><td><code>frame contains &quot;IAPBIN&quot;</code></td><td>直接在字节里搜帧头魔数</td></tr></tbody></table><p>看 TCP 流量时特别值得关注的标志：<strong>有没有重传（Retransmission）</strong>。同一段数据被发两遍，说明 ACK 没回到发送方——直连实验里出现大量重传，多半是对端处理太慢（比如板子在回调里做了耗时操作）。</p><h3 id="_3-对照本工程的三种典型包" tabindex="-1">3. 对照本工程的三种典型包 <a class="header-anchor" href="#_3-对照本工程的三种典型包" aria-label="Permalink to &quot;3. 对照本工程的三种典型包&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>线上应该看到什么</th><th>说明</th></tr></thead><tbody><tr><td>首次 ping</td><td>ARP 请求（广播）→ ARP 应答（单播）→ ICMP 请求 → ICMP 应答</td><td>四包齐全才算全通</td></tr><tr><td>TCP 升级</td><td>SYN → SYN/ACK → ACK → 数据段（每个段有 ACK）</td><td>缺握手先查端口；缺 ACK 看板子回调</td></tr><tr><td>TFTP 升级</td><td>RRQ（到 69）→ DATA（从服务器的 TID 端口）→ ACK → …</td><td>服务器会换端口，注意第二条的方向</td></tr></tbody></table><p>三个包的详细解析分别见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.html">LV050</a>、<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.html">LV035-传输层端口UDP与TCP</a> 第三节、<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07.html">LV025-基于TFTP的网络升级实验</a> 第五节。</p><h2 id="五、-症状到工具的对照表" tabindex="-1">五、 症状到工具的对照表 <a class="header-anchor" href="#五、-症状到工具的对照表" aria-label="Permalink to &quot;五、 症状到工具的对照表&quot;">​</a></h2><p>把前面几篇和本篇合起来，得到一张&quot;先拿什么工具&quot;的对照表：</p><table tabindex="0"><thead><tr><th>现象</th><th>第一个工具</th><th>看什么</th><th>大概率结论</th></tr></thead><tbody><tr><td>完全不通，灯也不亮</td><td>肉眼 + <code>ipconfig</code></td><td>网线、网卡选对没</td><td>物理层问题</td></tr><tr><td>ping 不通，灯亮</td><td><code>ipconfig</code></td><td>两边是否同网段、是不是配错了网卡</td><td>地址配置问题</td></tr><tr><td>ping 不通，网段正确</td><td><code>arp -a</code></td><td>有没有学到板子的 MAC</td><td>ARP 没通，查收包路径</td></tr><tr><td>ping 通，TCP 连不上</td><td><code>nc -v</code></td><td>refused 还是 timeout</td><td>端口没开 vs 链路问题</td></tr><tr><td>TCP 连上但升级失败</td><td>Wireshark</td><td>握手正常吗、有没有重传、帧头对不对</td><td>帧协议问题</td></tr><tr><td>TFTP 一直超时</td><td>Wireshark</td><td>RRQ 出去了吗、服务器回了吗</td><td>服务器没起或端口被拦</td></tr><tr><td>时通时不通</td><td><code>ping -t</code> 长ping + 板子计数</td><td>丢包有没有规律、主循环是否被堵</td><td>主循环被长操作挡住</td></tr></tbody></table><p>这张表与 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.html">LV050</a> 第六节的决策树是配套的：决策树解决&quot;按什么顺序查&quot;，这张表解决&quot;每一步用什么工具看&quot;。</p><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>日志只能覆盖一个观测点；抓包才能看到&quot;线上真实发生了什么&quot;，两者要配合用。</li><li><code>ping</code> 看时延、TTL 与丢包；<code>arp -a</code> / <code>ip neigh</code> 看解析结果；<code>ipconfig</code> / <code>ip addr</code> 先确认网卡选对。</li><li><code>nc -v</code> 把 TCP 与应用层解耦：握手成功 = 传输层全通；<code>refused</code> 是&quot;IP 通了、端口没开&quot;的好消息。</li><li><code>tcpdump -w</code> 录文件、<code>Wireshark</code> 里按过滤表达式分析，是嵌入式现场最实用的抓包组合。</li><li>看 TCP 流量重点关注重传；看 TFTP 流量注意服务器会换 TID 端口。</li><li>排查顺序永远是&quot;先物理、再地址、再 ARP、再传输层&quot;，每一步用对应的工具验证。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>排错决策树与实测输出：<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.html">LV050-一次ping的完整旅程</a> 第六节</li><li>驱动计数（主循环被堵的判据）：<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5187d4be5a1c9.html">LV005-DM9000驱动实现</a> 第六节</li><li>实验中的工具用法：<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a></li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第 1.6 节</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,59)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
